def largest_k_multiple_free_subset(n, k, numbers):
    numbers.sort()
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if numbers[i] % numbers[j] == 0 and numbers[i] // numbers[j] == k:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

